sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var riskVal = current.getValue('u_risk_score') || current.getValue('risk_score') || '0';
    var risk = parseInt(riskVal, 10);
    var statusVal = current.getValue('u_status') || current.getValue('status');

    // Trigger safety lockout if risk score is 80 or above and tool is not already blocked
    if (risk >= 80 && statusVal !== 'Blocked') {
        if (current.isValidField('u_status')) {
            current.setValue('u_status', 'Blocked');
        } else {
            current.setValue('status', 'Blocked');
        }

        // Display high-visibility red error message on screen
        gs.addErrorMessage("CRITICAL SAFETY LOCKOUT: Risk Score (" + risk + "/100) exceeded safe operational threshold (80). Tool status automatically updated to BLOCKED.");
    }

})(current, previous);
